# A namespace matching datamunge::nn. Numerical components are C++; experiment loops stay in R.
# The native classes are R6 classes (generated by Rosetta); this namespace keeps C++'s construction
# syntax, so nn$ParameterStore(9L) is ParameterStore$new(9L). Class statics also appear under their
# flat C++-style names (nn$FrozenGraph_load), and enums are lists of enumerator names.
nn <- new.env(parent = emptyenv())
.local_nn_constructor <- function(generator) {
  force(generator)
  constructor <- function(...) generator$new(...)
  attr(constructor, "generator") <- generator
  constructor
}
.local_nn_statics <- function(generator) {
  members <- ls(generator, all.names = FALSE)
  members[vapply(members, function(name) is.function(generator[[name]]) &&
    !name %in% c("new", "set", "get_inherit", "has_private", "debug", "undebug", "lock", "unlock", "is_locked"), logical(1))]
}
.local_nn_native_exports <- function() {
  namespace <- environment(.local_nn_native_exports)
  setNames(lapply(.rosetta_exports, get, envir = namespace), .rosetta_exports)
}
# Adds one native export to a group, the C++ way: classes construct, statics and enumerators stay flat.
.local_nn_add <- function(group, name, value, wrap = identity) {
  if (inherits(value, "R6ClassGenerator")) {
    group[[name]] <- wrap(.local_nn_constructor(value))
    for (member in .local_nn_statics(value)) group[[paste0(name, "_", member)]] <- wrap(value[[member]])
  } else if (is.function(value)) {
    group[[name]] <- wrap(value)
  } else if (is.list(value) && all(vapply(value, is.character, logical(1)))) {
    group[[name]] <- value
    for (item in names(value)) group[[paste0(name, "_", item)]] <- value[[item]]
  }
}
.local_nn_populate <- function() {
  exports <- .local_nn_native_exports()
  for (name in names(exports)) if (!grepl("__", name, fixed = TRUE)) .local_nn_add(nn, name, exports[[name]])
  namespace <- environment(.local_nn_populate)
  prefixed <- function(prefix) {
    selected <- names(exports)[startsWith(names(exports), prefix) & !grepl("__", names(exports), fixed = TRUE)]
    setNames(lapply(selected, function(name) exports[[name]]), substring(selected, nchar(prefix) + 1L))
  }
  nn$init <- prefixed("init_")
  nn$augment <- prefixed("augment_")
  nn$schedule <- prefixed("schedule_")
  nn$no_grad <- function(code) {
    previous <- is_grad_enabled()
    on.exit(set_grad_enabled(previous), add = TRUE)
    set_grad_enabled(FALSE)
    code()
  }
}
# Shared example components (examples/nn/common/*.hpp) regrouped by C++ namespace: C++
# image_training::ImageBatch is nn_components$image_training$ImageBatch. The R examples run the
# same loops as the C++ examples over these pieces.
nn_components <- new.env(parent = emptyenv())
.local_nn_component_namespaces <- c("example_runtime", "paths", "dataset_assets", "check", "image_training", "resnet", "resnet_demo",
                                    "architecture", "mobile_checks", "nn_components", "grouped", "lrn", "inception",
                                    "normalized_conv", "deconvnet", "alexnet", "googlenet", "inception23", "inception4",
                                    "nin", "vgg", "xception", "zfnet", "preact", "densenet", "dpn", "pyramidnet",
                                    "res2net", "resnext", "revnet", "stochastic_depth", "wide_resnet", "mobilenet",
                                    "mbconv", "condensenet", "ghostnet", "regnet", "shufflenet", "squeezenet", "convnext",
                                    "deformable", "non_local", "octconv", "repvgg", "attention_cnn", "mnist",
                                    "cnn_baselines", "alexnet_checks", "xception_checks", "densenet_checks", "ghostnet_checks", "mobilenet_v2_checks", "mnasnet_checks", "convnext_checks", "efficientnet_checks", "efficientnet_v2_checks", "preactivation_resnet_checks", "pyramidnet_checks", "res2net_checks", "resnext_checks", "revnet_checks", "cbam_checks", "non_local_checks", "octconv_checks", "repvgg_checks", "sknet_checks", "ae", "memory_components",
                                    "seg", "fcn", "unet", "segnet", "hrnet", "pspnet", "deeplab", "sentence", "replay", "series", "sensor", "charcnn", "tcn", "wavestack", "sal", "dream", "featurevis", "cam", "occlusion", "ig", "smooth", "guided", "detector", "fpn", "retinanet", "fcos", "ssd", "centernet", "detr", "hungarian", "efficientdet", "bifpn",
                                    "yolo", "wordtree", "maskrcnn", "instance", "panoptic", "yolact", "detection_evaluation", "detection", "highway", "stn", "capsnet", "im2col", "receptive")
.local_nn_populate_components <- function() {
  exports <- .local_nn_native_exports()
  # Flush R's buffered output before a C++ call so std::cout text stays in order.
  flushing <- function(value) {
    force(value)
    function(...) { flush(stdout()); value(...) }
  }
  for (prefix in .local_nn_component_namespaces) {
    marker <- paste0(prefix, "__")
    group <- new.env(parent = emptyenv())
    for (name in names(exports)[startsWith(names(exports), marker)])
      .local_nn_add(group, substring(name, nchar(marker) + 1L), exports[[name]], flushing)
    nn_components[[prefix]] <- group
  }
}

# Vectors of tensors cross as R lists. These helpers remain for code written against the SWIG
# bindings, which needed explicit native vectors.
.local_nn_tensor_list <- function(vector) if (is.list(vector)) vector else list(vector)
.local_nn_tensor_vector <- function(values) values
# Named tensors (C++ vectors of name/tensor pairs) as R named lists.
.local_nn_named_list <- function(pairs) {
  if (!length(pairs)) return(setNames(list(), character()))
  setNames(lapply(pairs, function(pair) pair$second), vapply(pairs, function(pair) pair$first, character(1)))
}
.local_nn_named_tensors <- function(arrays) {
  if (!is.list(arrays) || !length(arrays)) return(list())
  if (!is.null(arrays[[1L]]$first)) return(arrays) # already name/tensor pairs
  if (is.null(names(arrays)) || base::any(!nzchar(names(arrays))) || anyDuplicated(names(arrays)))
    stop("arrays must have unique nonempty names")
  unname(Map(function(name, tensor) list(first = name, second = tensor), names(arrays), arrays))
}
.local_nn_load_npz <- function(path) .local_nn_named_list(load_npz(path))
.local_nn_save_npz <- function(path, arrays) save_npz(path, .local_nn_named_tensors(arrays))
.local_nn_grad <- function(output, inputs, options = GradOptions$new(), grad_outputs = NULL) {
  if (is.list(output) || !is.null(grad_outputs)) {
    if (!is.list(output)) output <- list(output)
    if (is.null(grad_outputs)) grad_outputs <- list()
    return(grad(output, inputs, grad_outputs, options))
  }
  grad(output, inputs, options)
}
# Validate R widths before converting numeric vectors to native int64 geometry.
.local_nn_autoencoder_widths <- function(widths) {
  if (!is.numeric(widths) || base::any(!is.finite(widths) | widths != base::floor(widths) |
                                     widths <= 0 | widths >= 2^63))
    stop("widths must be positive whole int64 dimensions")
  widths
}
.local_nn_image_size <- function(size) {
  if (!is.numeric(size)) return(size) # Already a bound C++ ImageSize.
  if (length(size) != 2L || base::any(!is.finite(size) | size != base::floor(size)))
    stop("image size must contain two finite integer dimensions")
  result <- ImageSize$new()
  result$height <- size[1L]
  result$width <- size[2L]
  result
}
.onLoad <- function(libname, pkgname) {
  .rosetta_onload(asNamespace(pkgname))
  .local_nn_populate()
  .local_nn_populate_components()
  nn$load_npz <- .local_nn_load_npz
  nn$save_npz <- .local_nn_save_npz
  nn$grad <- .local_nn_grad
  nn$tensor_list <- .local_nn_tensor_list
  nn$tensor_vector <- .local_nn_tensor_vector
  nn$named_tensors <- .local_nn_named_tensors
  nn$named_list <- .local_nn_named_list
  # Native fitting-only standardization/axis selection, owning detached arrays.
  # Test R2 is unbounded below and each test target must vary; no VAE fitting is hidden.
  nn$LatentFactorDiagnostics <- function(fit_mu, test_mu, fit_factors, test_factors, fit_log_variance, ridge=.001)
    .local_nn_named_list(LatentFactorDiagnostics(fit_mu, test_mu, fit_factors, test_factors, fit_log_variance, ridge))
  nn$KnownFactorLattice <- function() .local_nn_named_list(KnownFactorLattice())
  nn$SequenceDataArrays <- function(pools) .local_nn_named_list(SequenceDataArrays(pools))
  nn$SigmoidAutoencoder <- function(parameters, image, widths)
    SigmoidAutoencoder(parameters, image, .local_nn_autoencoder_widths(widths))
  nn$SigmoidAutoencoderDecode <- function(parameters, code, widths)
    SigmoidAutoencoderDecode(parameters, code, .local_nn_autoencoder_widths(widths))
  nn$resize_bilinear <- function(images, size, align_corners = FALSE, half_pixel_centers = FALSE)
    resize_bilinear(images, .local_nn_image_size(size), align_corners, half_pixel_centers)
  nn$resize_nearest <- function(images, size, align_corners = FALSE, half_pixel_centers = FALSE)
    resize_nearest(images, .local_nn_image_size(size), align_corners, half_pixel_centers)
}
